static bool plant_wifi_check_link(int sock)
{
  char essid[WAPI_ESSID_MAX_SIZE + 1];
  enum wapi_essid_flag_e flag;
  int ret;

  ret = wapi_get_essid(sock, WLAN_DEVICE, essid, &flag);
  if (ret < 0)
    {
      printf("plant_wifi: get_essid failed: %d\n", ret);
      return false;
