int plant_wifi_connect(const char *ssid, const char *password)
{
  struct plant_wifi_ctx_s *ctx = &g_wifi_ctx;
  struct wpa_wconfig_s wconfig;
  struct in_addr addr;
  int sock;
  int ret;
  int dhcp_retry;
  bool associated = false;

  if (!ctx->initialized || ssid == NULL)
    {
      return -EINVAL;
    }

  printf("plant_wifi: Connecting to %s...\n", ssid);

  /* ���� 1. ���� ioctl socket ���� */

  sock = wapi_make_socket();
  if (sock < 0)
    {
      printf("plant_wifi: Failed to create socket: %d\n", errno);
      return -errno;
    }

  /* ���� 2. ���� wlan0 ����ӿ� ���� */

  ret = wapi_set_ifup(sock, WLAN_DEVICE);
  if (ret < 0)
    {
      printf("plant_wifi: Failed to bring up %s: %d\n",
             WLAN_DEVICE, errno);
      close(sock);
      return -errno;
    }

  /* ���� 3. ���� WPA2 �������� ���� */

  memset(&wconfig, 0, sizeof(wconfig));
  wconfig.sta_mode    = IW_MODE_INFRA;
  wconfig.auth_wpa    = IW_AUTH_WPA_VERSION_WPA2;
  wconfig.cipher_mode = IW_AUTH_CIPHER_CCMP;
  wconfig.alg         = WPA_ALG_CCMP;
  wconfig.freq        = 0.0;                   /* �Զ�ѡ��Ƶ�� */
  wconfig.ssidlen     = strlen(ssid);
  wconfig.ifname      = WLAN_DEVICE;
  wconfig.ssid        = ssid;

  if (password != NULL && password[0] != '\0')
    {
      wconfig.phraselen  = strlen(password);
      wconfig.passphrase = password;
    }

  /* ���� 4. ִ�й��� ����
   *
   * wpa_driver_wext_associate() �� ioctl ����˳��
   *   SIOCSIWMODE      �� esp_wifi_sta_mode()      ���� Infra ģʽ
   *   SIOCSIWAUTH      �� esp_wifi_sta_auth()      ���� WPA2
   *   SIOCSIWAUTH      �� esp_wifi_sta_auth()      ���� CCMP ����
   *   SIOCSIWENCODEEXT �� esp_wifi_sta_password()  ��������
   *   SIOCSIWESSID     �� esp_wifi_sta_essid()     ���� SSID + ��������
   *
   * esp_wifi_sta_connect() ��ͬ���ģ��ڲ��������ȴ�
   * g_sta_connected �źţ���ʱ CONFIG_ESP32S3_WIFI_CONNECT_TIMEOUT=30�룩��
   */

  printf("plant_wifi: Associating...\n");
  ret = wpa_driver_wext_associate(&wconfig);
  if (ret < 0)
    {
      printf("plant_wifi: Association failed: %d\n", ret);
      close(sock);
      return ret;
    }

  /* ���� 5. �ȴ���·�������ȴ�������������ȫ�ȶ��� ���� */

  sleep(LINK_READY_WAIT_SEC);

  /* ��֤����״̬ */
  associated = plant_wifi_check_link(sock);
  if (!associated)
    {
      printf("plant_wifi: Link not established after association\n");
      close(sock);
      return -ENETUNREACH;
    }

  printf("plant_wifi: Association confirmed, requesting IP via DHCP...\n");

  /* ���� 6. ͨ�� DHCP ��ȡ IP ��ַ ����
   *
   * netlib_obtain_ipv4addr() �ڲ����� dhcpc��
   *   dhcpc_open() �� dhcpc_request() �� dhcp_setup_result()
   *
   * DHCPC �������ã����� .config����
   *   CONFIG_NETUTILS_DHCPC_RECV_TIMEOUT_MS=3000
   *   CONFIG_NETUTILS_DHCPC_RETRIES=3
   *   ���ε����Լ 9 ��
   */

  for (dhcp_retry = 0; dhcp_retry < DHCP_MAX_RETRY; dhcp_retry++)
    {
      ret = netlib_obtain_ipv4addr(WLAN_DEVICE);
      if (ret == 0)
        {
          /* DHCP �ɹ�����ȡ����� IP ��ַ */
          ret = wapi_get_ip(sock, WLAN_DEVICE, &addr);
          if (ret == 0 && addr.s_addr != INADDR_ANY)
            {
              printf("plant_wifi: DHCP OK, IP: %s\n", inet_ntoa(addr));
              break;
            }

          /* ��ȡ�� IP ����ַ��Ч���������� */
          printf("plant_wifi: DHCP returned but IP is INADDR_ANY, retrying...\n");
        }
      else
        {
          printf("plant_wifi: DHCP attempt %d/%d failed: %d\n",
                 dhcp_retry + 1, DHCP_MAX_RETRY, ret);
        }

      if (dhcp_retry < DHCP_MAX_RETRY - 1)
        {
          sleep(DHCP_RETRY_INTVL);
        }
    }

  close(sock);

  /* ���� 7. ��� DHCP ��� ���� */

  if (dhcp_retry >= DHCP_MAX_RETRY)
    {
      printf("plant_wifi: DHCP failed after %d attempts, "
