  /* ���� 8. ���ӳɹ� ���� */

  strlcpy(ctx->ssid, ssid, sizeof(ctx->ssid));
  ctx->connected = true;

  printf("plant_wifi: WiFi connected to %s (IP: %s)\n",
         ssid, inet_ntoa(addr));
