int plant_wifi_disconnect(void)
{
  struct plant_wifi_ctx_s *ctx = &g_wifi_ctx;
  int sock;
  int ret;

  sock = wapi_make_socket();
  if (sock < 0)
    {
      return -errno;
    }

  ret = wapi_set_ifdown(sock, WLAN_DEVICE);
  close(sock);

  if (ret == 0)
    {
      ctx->connected = false;
      syslog(LOG_INFO, TAG": Disconnected\n");
    }

  return ret;
}

bool plant_wifi_is_connected(void)
{
  struct plant_wifi_ctx_s *ctx = &g_wifi_ctx;
  return ctx->connected;
}

void plant_wifi_deinit(void)
{
  struct plant_wifi_ctx_s *ctx = &g_wifi_ctx;

  if (ctx->connected)
    {
      plant_wifi_disconnect();
    }

  ctx->initialized = false;
  syslog(LOG_INFO, TAG": WiFi module deinitialized\n");
}

