/****************************************************************************
 * 3C-2 图像识别：上传 RGB565 帧 → 服务器转 JPEG → MiMo 诊断 → 文本
 *
 * 协议：POST /image/analyze   body = RGB565 160×120 原始帧（38400B）
 *       响应 JSON {ok:true, text:"..."}
 * 与语音同架构：设备无 TLS 直连 MiMo，走局域网服务器中转。
 ****************************************************************************/

int server_bridge_image_analyze(const uint8_t *frame, size_t frame_len,
                                char *text_out, size_t text_size)
{
  char path[32];
  static char resp[SB_RESP_MAX];   /* static: 8KB worker 栈放不下 4096 */
  int ret;

  if (g_sb_host[0] == '\0')
    {
      return -ENOTCONN;
    }

  snprintf(path, sizeof(path), "/image/analyze");

  /* ⚠️ 3C-2 超时：图像识别服务器端（PIL 转 JPEG + MiMo 视觉）通常
   * 10-30s，60s 足够且比语音的 180s 更早失败反馈（服务器不可达时
   * UI 不会卡死——worker 独立线程，超时后降级演示兜底）。 */

  ret = sb_http_post(g_sb_host, g_sb_port, path,
                     "application/octet-stream",
                     frame, frame_len,
                     resp, sizeof(resp), 60000);
  if (ret < 0)
    {
      printf("[Bridge] image analyze HTTP failed: %d\n", ret);
      return ret;
    }

  if (sb_json_get_string(resp, "text", text_out, text_size) < 0)
    {
      printf("[Bridge] image analyze: no text in response "
             "(%d bytes)\n", ret);
      text_out[0] = '\0';
      return -EINVAL;
    }

  return 0;
}

/****************************************************************************
 * 阶段 B 实时时间：GET /time → 服务器返回北京时间（UTC+8）。
 * unix_beijing 填北京时间 unix 秒（已偏移），date_out 填 "YYYY-MM-DD"，
 * time_out 填 "HH:MM"。响应 <1KB（静态缓冲）；失败返回负 errno
 * （-ENOTCONN=未配置服务器）。
 ****************************************************************************/

int server_bridge_get_time(int64_t *unix_beijing,
                           char *date_out, size_t date_size,
                           char *time_out, size_t time_size)
{
  static char resp[1024];   /* static: 8KB worker 栈放不下 1KB */
  int ret;

  if (g_sb_host[0] == '\0')
    {
      return -ENOTCONN;
    }

  ret = sb_http_get(g_sb_host, g_sb_port, "/time",
                    resp, sizeof(resp), SB_TIMEOUT_MS);
  if (ret < 0)
    {
      return ret;
    }

  if (unix_beijing != NULL)
    {
      *unix_beijing = 0;

      /* "unix" 是 JSON 整数（无引号），单独解析（同 has_audio 布尔模式） */

      {
        const char *q = strstr(resp, "\"unix\"");

        if (q != NULL)
          {
            q += strlen("\"unix\"");
            while (*q == ' ' || *q == ':' || *q == '\t')
              {
                q++;
              }

            *unix_beijing = (int64_t)strtoll(q, NULL, 10);
          }
      }
    }

  if (date_out != NULL && date_size > 0)
    {
      if (sb_json_get_string(resp, "date", date_out, date_size) < 0)
        {
          date_out[0] = '\0';
        }
    }

  if (time_out != NULL && time_size > 0)
    {
      if (sb_json_get_string(resp, "time", time_out, time_size) < 0)
        {
          time_out[0] = '\0';
        }
    }

  return 0;
}

