static int sb_json_get_string(const char *json, const char *key,
                              char *out, size_t out_size)
{
  char pat[64];
  const char *p;
  const char *v;

  snprintf(pat, sizeof(pat), "\"%s\"", key);
  p = strstr(json, pat);
  if (p == NULL)
    {
      return -ENOENT;
    }

  p += strlen(pat);
  while (*p == ' ' || *p == ':' || *p == '\t')
    {
      p++;
    }

  if (*p != '"')
    {
      return -EINVAL;
    }

  p++;
  v = p;
  while (*p != '\0' && *p != '"')
    {
      p++;
    }

  if (*p != '"' || (size_t)(p - v) >= out_size)
    {
      return -EINVAL;
    }

  memcpy(out, v, p - v);
  out[p - v] = '\0';
  return (int)(p - v);
}

