   * 取消标志被清掉、录音照常开始。这里在录音前再查一次 g_cancel。 */

  pthread_mutex_lock(&g_lock);
  cancelled = g_cancel;
  pthread_mutex_unlock(&g_lock);
  if (cancelled)
    {
      printf("[Voice] 已取消（录音前），本次会话丢弃\n");
      set_state(VOICE_STATE_IDLE);
      pthread_mutex_lock(&g_lock);
      g_busy = false;
      g_cancel = false;
      pthread_mutex_unlock(&g_lock);
      return NULL;
    }

  /* 2. 流式录音（≤5s，静音 1.5s 自动停，再点按键=取消）→ 每块上传 */

  set_state(VOICE_STATE_LISTENING);
  ms = ai_voice_stream_record(voice_upload_cb, NULL, 5, 15);
  if (ms < 0)
    {
      printf("[Voice] stream record failed: %d\n", ms);
      set_state(VOICE_STATE_IDLE);
      pthread_mutex_lock(&g_lock);
      g_busy = false;
      g_cancel = false;
      pthread_mutex_unlock(&g_lock);
      return NULL;
    }

  if (ms < 300)
    {
      /* 录音太短（几乎静音 / 说完前就点了）→ 不打扰，静默回 IDLE */

      set_state(VOICE_STATE_IDLE);
      pthread_mutex_lock(&g_lock);
      g_busy = false;
      g_cancel = false;
      pthread_mutex_unlock(&g_lock);
      return NULL;
    }

  /* ⚠️ 2026-08-31 交互修正：录音中再点按键 = 「说完」→ 保留已录内容
