 * Public Functions
 ****************************************************************************/

int ai_service_init(void)
{
  int ret;

  pthread_mutex_lock(&g_lock);
  if (g_inited)
    {
      pthread_mutex_unlock(&g_lock);
      return 0;
    }

  ret = ai_engine_init();
  if (ret == 0)
    {
      g_inited = true;
    }

  pthread_mutex_unlock(&g_lock);

