    {
      lv_point_t pt;

      g_tdiag_lv_press++;
      lv_indev_get_point(g_ui_result.indev, &pt);
      g_tdiag_lv_x = (uint32_t)pt.x;
      g_tdiag_lv_y = (uint32_t)pt.y;
      g_tdiag_lv_press_ms = lv_tick_get();
    }

  g_tdiag_last_lv_state = st;
}

