    /* 3C-2 真实链路（零拷贝 + 杀进程）：
     * 1) 先 take()（freeze）：预览线程退出 capture 路径进入空转
     *    （否则 stop 的 join 会等当前 capture 超时 ~10s，UI 卡）；
     * 2) rxbuf 是静态 DRAM（38400B），stop 后不清零 → 帧保留；
     * 3) camera_preview_stop() 杀掉预览线程 + DMA（用户要求）；
     * 4) worker 借用 rxbuf（borrowed=true），读静态内存安全；
     * 5) 无 PSRAM 堆仅 ~17KB，malloc 38KB 必失败 → 零拷贝唯一路径。 */
    const uint8_t *fb;
    int ret;

    camera_preview_take();          /* 先冻结：线程进入空转，stop 不等待 */
    fb = camera_preview_get_frame();

    if (fb != NULL)
      {
        ret = ai_service_analyze_async(fb, CAM_PREVIEW_SIZE, true, NULL,
                                       cam_ai_done, NULL);
        if (ret != 0)
          {
            if (s_status_label != NULL)
              {
                lv_label_set_text(s_status_label, "识别忙，稍后再试");
              }
          }
      }
    else
      {
        cam_ai_done(NULL, NULL);   /* 无帧 → 演示兜底 */
      }

    /* 杀掉摄像头进程（线程 + DMA）。freeze 后线程在空转，join 立即返回。
     * rxbuf 静态保留，worker 仍可读。返回本页时 frame_timer 重启预览。
     * ⚠️ s_cam_busy=true：诊断等待期（worker 上传 10-30s）禁止 frame_timer
