                 "input_audio": {"data": "data:audio/wav;base64," + b64}},
                {"type": "text", "text": AUDIO_PROMPT}]}],
            "max_completion_tokens": 1024,
        }
        return self._mimo_chat(payload, timeout=60)

    # ── 对外：文本问答 ──
    def chat_text(self, text, history=None):
        if self.mode == "mock":
