  s_ai_failed = true;
  s_ai_error[0] = '\0';

  if (result != NULL && result->success && result->from_server)
    {
      /* 服务器真实结构化结果：正常走诊断页 */
      s_ai_failed = false;
      s_ai_diag = result->diag;
