```c
#include <nuttx/config.h>
#include <stdio.h>
#include <string.h>
#include <errno.h>

#include "sd_card.h"
#include "device_cfg.h"

#define PLANT_CFG_PATH  SD_MOUNTPOINT "/plant.cfg"

int device_cfg_save(const char *ssid, const char *password,
                    const char *host, uint16_t port)
{
  FILE *fp;

  if (!sd_card_status() && sd_card_mount() < 0)
    {
      return -EIO;
    }

  fp = fopen(PLANT_CFG_PATH, "w");
  if (fp == NULL)
    {
      return -errno;
    }

  fprintf(fp, "# plant-companion boot config\n");
  if (ssid != NULL && ssid[0] != '\0')
    {
      fprintf(fp, "wifi_ssid=%s\n", ssid);
      if (password != NULL)
        fprintf(fp, "wifi_password=%s\n", password);
    }
  if (host != NULL && host[0] != '\0')
    {
      fprintf(fp, "server_host=%s\n", host);
      fprintf(fp, "server_port=%u\n", (unsigned)port);
    }
  if (fclose(fp) != 0) return -errno;
  return 0;
}
```
