+              *port = (uint16_t)atoi(line + 12);
+            }
+        }
+    }
+
+  fclose(fp);
+  return 0;
+}
+
+int device_cfg_clear(void)
+{
+  if (cfg_ensure_mounted() < 0)
+    {
+      return -EIO;
+    }
+
+  if (remove(PLANT_CFG_PATH) == 0)
+    {
+      return 0;
+    }
+
+  return (errno == ENOENT) ? 0 : -errno;
+}
