/* 开机自动恢复线程：UI 启动后并行执行，等 SD 上电预热（最长约 40s）。 */
static void *boot_cfg_thread(void *arg)
{
  int waited = 0;
  (void)arg;

  while (!sd_card_status() && waited < 40)
    {
      usleep(1000 * 1000);
      waited++;
