+
+#ifdef CONFIG_PLANT_AI_MODULE
+  if (host[0] != '\0')
+    {
+      uint16_t use_port = (port != 0) ? port : 8000;
+
+      ret = server_bridge_set_server(host, use_port);
+      if (verbose || ret != 0)
+        {
+          printf("[Cfg] 配置服务器 %s:%u → %d\n", host,
