void screen_diagnose_set(lv_obj_t *scr,
                         const char *name, const char *latin,
                         int match, const char *tags,
                         const char *section_title,
                         bool issue, const char *issue_desc,
                         const char *advice)
{
  char buf[64];
  (void)scr;

  if (s_warn_title != NULL)
    {
      const char *title = (section_title != NULL && section_title[0] != '\0')
                          ? section_title : "⚠ 发现小问题";

      lv_label_set_text(s_warn_title, title);
    }

  if (s_name != NULL)
    {
      snprintf(buf, sizeof(buf), "🌿 %s", name != NULL ? name : "未知");
      lv_label_set_text(s_name, buf);
    }

  if (s_latin != NULL)
    {
      lv_label_set_text(s_latin, latin != NULL ? latin : "");
    }

  if (s_match != NULL)
    {
      snprintf(buf, sizeof(buf), "✅ 匹配度 %d%%", match);
      lv_label_set_text(s_match, buf);
    }

  if (s_tags != NULL)
    {
      lv_label_set_text(s_tags, tags != NULL ? tags : "");
    }

  if (s_warn_box != NULL)
    {
      if (issue)
        {
          lv_obj_remove_flag(s_warn_box, LV_OBJ_FLAG_HIDDEN);
        }
      else
        {
          lv_obj_add_flag(s_warn_box, LV_OBJ_FLAG_HIDDEN);
        }
    }

  if (s_issue_desc != NULL)
    {
      lv_label_set_text(s_issue_desc, issue_desc != NULL ? issue_desc : "");
    }

  if (s_advice != NULL)
    {
      lv_label_set_text(s_advice, advice != NULL ? advice : "");
    }
}

